use eframe::egui::{self, FontDefinitions, FontData, FontFamily, FontId, TextStyle};
use std::path::Path;
fn load(ctx:&egui::Context, name:&str, file:&str)->bool { let p=Path::new(r"C:\Windows\Fonts").join(file); match std::fs::read(&p) { Ok(bytes)=>{ let mut f=FontDefinitions::default(); f.font_data.insert(name.into(), FontData::from_owned(bytes).into()); for fam in [FontFamily::Proportional,FontFamily::Monospace] { f.families.entry(fam).or_default().insert(0,name.into()); } ctx.set_fonts(f); true }, Err(_)=>false } }
pub fn install(ctx:&egui::Context) { let mut ok=load(ctx,"matcha-segoe","segoeui.ttf"); ok &= load(ctx,"matcha-mono","consola.ttf"); let _=load(ctx,"matcha-cjk","msyh.ttc"); if !ok { eprintln!("matcha: system UI/editor font unavailable; using egui built-in fallback"); } ctx.all_styles_mut(|s| { s.text_styles.insert(TextStyle::Body,FontId::proportional(12.0)); s.text_styles.insert(TextStyle::Button,FontId::proportional(12.0)); s.text_styles.insert(TextStyle::Monospace,FontId::monospace(12.0)); }); }
#[cfg(test)] mod tests { #[test] fn missing_font_falls_back_without_panic(){ assert!(!std::path::Path::new(r"C:\Windows\Fonts\__missing__.ttf").exists()); } }
